using HomestayBooking.Desktop.Models;
using System.Text.Json;
namespace HomestayBooking.Desktop.View;
public partial class FrmBookingManagement : Form
{
    private int _page=1;private int _totalPages=1;
    public FrmBookingManagement(){InitializeComponent();cboStatus.SelectedIndex=0;Load+=async (_,_)=>{await LoadAssigneesAsync();await RefreshAsync();};btnSearch.Click+=async(_,_)=>{_page=1;await RefreshAsync();};btnPrev.Click+=async(_,_)=>{if(_page>1){_page--;await RefreshAsync();}};btnNext.Click+=async(_,_)=>{if(_page<_totalPages){_page++;await RefreshAsync();}};btnAssignBooking.Click+=async(_,_)=>await AssignAsync();btnUpdateStatus.Click+=async(_,_)=>await UpdateStatusAsync();dgvBookings.CurrentCellChanged+=async(_,_)=>await LoadDetailsAsync();}
    private async Task LoadAssigneesAsync(){try{var rows=await DesktopApi.GetAllAsync<JsonElement>("assignees");cboAssignTo.DisplayMember="label";cboAssignTo.ValueMember="employeeId";cboAssignTo.DataSource=rows.Select(a=>new{employeeId=a.GetProperty("employeeId").GetInt32(),label=$"{a.GetProperty("employeeCode").GetString()} · {a.GetProperty("fullName").GetString()}"}).ToList();}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
    private async Task RefreshAsync(){try{var status=cboStatus.SelectedIndex>0?$"&status={cboStatus.Text}":"";var data=await DesktopApi.GetAsync<JsonElement>($"bookings?q={Uri.EscapeDataString(txtSearchQ.Text)}{status}&page={_page}");_page=data.GetProperty("page").GetInt32();_totalPages=data.GetProperty("totalPages").GetInt32();dgvBookings.DataSource=DesktopApi.ToTable(data.GetProperty("items").EnumerateArray());DesktopApi.ShowColumns(dgvBookings,("code","Mã đơn"),("contactName","Khách"),("contactPhone","SĐT"),("homestayName","Homestay"),("roomTypeName","Loại phòng"),("checkIn","Nhận phòng"),("checkOut","Trả phòng"),("status","Trạng thái"),("amountDue","Tiền cọc"),("assignedEmployeeName","Phụ trách"));lblPage.Text=$"Trang {_page} / {_totalPages} · {data.GetProperty("totalCount").GetInt32()} đơn";btnPrev.Enabled=_page>1;btnNext.Enabled=_page<_totalPages;}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
    private async Task LoadDetailsAsync(){try{if(dgvBookings.CurrentRow is null)return;var id=ReadInt(dgvBookings.CurrentRow.Cells["id"].Value);var d=await DesktopApi.GetAsync<JsonElement>($"bookings/{id}");dgvBookingNights.DataSource=List(d,"nights");dgvStatusHistory.DataSource=List(d,"history");dgvPayments.DataSource=List(d,"payments");dgvChangeRequests.DataSource=List(d,"changes");dgvAuditLogs.DataSource=List(d,"audit");}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
    private static System.Data.DataTable List(JsonElement d,string prop)=>DesktopApi.ToTable(d.GetProperty(prop).EnumerateArray());
    private async Task AssignAsync(){try{await DesktopApi.PostAsync<object>($"bookings/{SelectedId}/assign",new{employeeId=cboAssignTo.SelectedValue});await RefreshAsync();}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
    private async Task UpdateStatusAsync(){try{int? roomId=string.IsNullOrWhiteSpace(txtNewRoomId.Text)?null:int.Parse(txtNewRoomId.Text);await DesktopApi.PostAsync<object>($"bookings/{SelectedId}/status",new{status=cboTargetStatus.Text,note=txtStatusNote.Text,newRoomId=roomId});await RefreshAsync();}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
    private int SelectedId=>dgvBookings.CurrentRow is null?0:ReadInt(dgvBookings.CurrentRow.Cells["id"].Value);
    private static int ReadInt(object? value)=>value is JsonElement e?e.GetInt32():Convert.ToInt32(value);
}
